INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 1, 'Evaluate condition: 4.12 Entitlement
Maximum CIF value of one or more authorisations to be issued under paragraph
4.07 of Handbook of Procedures shall be as under:
(i) For Status Holders – up to 300% of FOB and / or FOR value of preceding
year’s exports and/or supplies.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 2, 'Evaluate condition: Value of such authorisations, subsequent to fixation of norms by Norms
