INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.44', 7, 'In addition, this information may be generated
from Computer System and maintained in a book form.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.44', 8, 'Copies of shipping bills shall be submitted to Regional Authority
concerned for verification within two months from date of expiry of
export obligation period.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.44', 9, 'In case an applicant is not able to upload any
prescribed document then such documents may be submitted in physical
form to the concerned authority.');
