INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP2023_Chapter04+as+on+20.04.2026.pdf', '4', 'Duty Exemption / Remission Schemes', '4.90', 'Re-import of rejected jewellery', '4.90 Re-import of rejected jewellery
An exporter of plain/ studded precious metal jewellery shall be allowed to re-
