INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.33', 6, 'Run validation: Designated officer
shall also exercise powers of adjudication under Section 13 read with Section 11
of FT(D&R) Act, 1992, as amended, in respect of STP / EHTP as mentioned in
Gazette Notification No.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.33', 7, 'Run validation: Similarly in case of units
under BTP, necessary approval / permission shall be granted by officer
designated by Do BT.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.33', 8, 'Handle exception: However, designated officers shall adopt criteria for
automatic approval of new units as laid down in Appendix 6A of Appendices &
ANFs.');
