INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('Chapter-7-of-HBP-2023.pdf', '7', 'Deemed Exports', '7.06', 'Rate of Drawback', 'However, an application in ANF-7A, along with documents prescribed in ANF-7A
& Appendix-7E, may be made to RA or DC concerned, as the case may be, for
fixation of brand rate where All Industry Rate of Drawback is not available or same
is less than 4/5th of duties actually paid on raw materials or components used in
